// Pick up rows a human typed into the Demo tab and has not been processed yet.
//
// A dedicated Demo tab, NOT the Leads tab. The Leads tab is written by the live intake pipeline,
// so polling it would re-trigger on rows this system itself just appended — a feedback loop
// against real spend. A separate input surface cannot loop.
//
// `status` is the claim marker: blank means unprocessed. Anything else (queued/done/skipped/an
// error string) means leave it alone. That makes a re-poll idempotent without needing a lock —
// the row's own state is the lock.
const rows = $input.all().map((i) => i.json || {});
const clean = (v, cap = 160) => (typeof v === 'string'
  ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, cap) : '');

const PRODUCTS = ['oryoniq', 'visioneerit', 'demo'];
const out = [];

for (const r of rows) {
  if (clean(r.status)) continue;                       // already claimed
  const first_name = clean(r.first_name, 80);
  const company    = clean(r.company, 160);
  const email      = clean(r.contact_email, 160).toLowerCase();
  if (!first_name && !company && !email) continue;     // blank spacer row

  const rowNum = r.row_number ?? r.__rowNum ?? null;
  const problems = [];
  if (!first_name) problems.push('first_name is blank');
  if (!company)    problems.push('company is blank');
  // Strict on purpose: a comma or bracket smuggled in here turns one row into two recipients.
  if (!/^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/.test(email)) {
    problems.push(email ? `'${email}' is not a single valid address` : 'contact_email is blank');
  }
  let product = clean(r.product, 40).toLowerCase() || 'demo';
  if (!PRODUCTS.includes(product)) {
    problems.push(`product '${product}' is not one of ${PRODUCTS.join('/')}`);
  }

  out.push({ json: {
    row_number: rowNum,
    first_name, company, email,
    title: clean(r.title, 120) || '(role)',
    product,
    // A bad row is REPORTED back into the sheet, never silently skipped — the person who typed it
    // is standing right there, and a row that vanishes looks like the system is broken.
    invalid: problems.length > 0,
    problems: problems.join('; '),
  }});
}

return out;

// Hand the drafting sub-workflow exactly the fields it reads, and carry the row identity so the
// result can be written back to the row the human is watching.
const r = $input.item.json;
return { json: {
  first_name: r.first_name,
  title: r.title,
  company: r.company,
  // The drafting workflow selects OryonIQ vs VisioneerIT copy from this. 'demo' is the demo
  // campaign, whose copy is OryonIQ's step 1 verbatim, so it drafts with the OryonIQ config.
  source_config: r.product === 'demo' ? 'oryoniq' : r.product,
  _row: r.row_number, _email: r.email, _product: r.product, _company: r.company,
  _first_name: r.first_name, _title: r.title,
} };

// Fold the drafted opener back onto the row, ready for the page + enrolment stages.
const d = $input.item.json;
const opener = typeof d.opener === 'string' ? d.opener.trim() : '';
return { json: {
  row_number: d._row, first_name: d._first_name, title: d._title, company: d._company,
  product: d._product, contact_email: d._email,
  opener,
  email_draft: typeof d.email === 'string' ? d.email : '',
  drafted: opener.length > 0,
} };

// Report the problem into the sheet rather than dropping the row silently.
const r = $input.item.json;
return { json: { row_number: r.row_number, status: 'skipped',
                 notes: `Not processed — ${r.problems}`, opener: '', email_draft: '',
                 sendr_page_url: '' } };

// Drafted, not yet sent. The enrolment step is gated and runs separately, so this row
// deliberately does NOT claim an email went out.
const r = $input.item.json;
return { json: { ...r, status: r.drafted ? 'drafted' : 'error',
  notes: r.drafted ? 'Drafted online. Enrolment is a separate approved step.'
                   : 'Drafting returned no opener.' } };

// Build the row update the human sees appear beside what they typed.
const scrub = (v) => (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ') : v);
const r = $input.item.json;
return { json: {
  row_number: r.row_number,
  status: r.status,
  opener: scrub(r.opener || ''),
  email_draft: scrub(r.email_draft || ''),
  sendr_page_url: r.sendr_page_url || '',
  notes: scrub(r.notes || ''),
  updated_at: new Date().toISOString(),
} };
